        title: apt.title,
        description: apt.description || '',
        time: apt.startTime,
        date: apt.date,
        type: apt.meetingType || 'meeting',
        status: apt.status,
        clientName: apt.clientName || '',
        clientEmail: apt.clientEmail || '',
